 "content": "def transform(grid):
    """Replace large solid rectangular patches with marker color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]

    # For each pair of row boundaries, find columns whose cells all match
    # throughout the span. Any run at least 25 cells in area is a patch.
    for top in range(h):
        for color in set(grid[top]):
            valid = [grid[top][c] == color for c in range(w)]
            for bottom in range(top, h):
                if bottom > top:
                    row = grid[bottom]
                    valid = [valid[c] and row[c] == color for c in range(w)]
                height = bottom - top + 1
                start = 0
                while start < w:
                    if not valid[start]:
                        start += 1
                        continue
                    end = start
                    while end < w and valid[end]:
                        end += 1
                    if height * (end - start) >= 25:
                        for r in range(top, bottom + 1):
                            for c in range(start, end):
                                marked[r][c] = True
                    start = end

    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
